			templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 37, "</div></div></div><script>\n\t\tdocument.addEventListener('DOMContentLoaded', function () {\n\t\t\tconst titleInput  = document.getElementById('title');\n\t\t\tconst authorInput = document.getElementById('author');\n\t\t\tconst coverInput  = document.getElementById('cover');\n\n\t\t\tconst previewTitle       = document.getElementById('preview-title');\n\t\t\tconst previewAuthor      = document.getElementById('preview-author');\n\t\t\tconst previewImg         = document.getElementById('preview-cover-img');\n\t\t\tconst previewPlaceholder = document.getElementById('preview-cover-placeholder');\n\t\t\tconst previewTags        = document.getElementById('preview-tags');\n\n\t\t\tconst fallbackTitle = titleInput?.placeholder || '';\n\n\t\t\tfunction syncTitle() {\n\t\t\t\tif (!previewTitle) return;\n\t\t\t\tpreviewTitle.textContent = titleInput.value.trim() || fallbackTitle;\n\t\t\t}\n\n\t\t\tfunction syncAuthor() {\n\t\t\t\tif (!previewAuthor) return;\n\t\t\t\tconst v = authorInput.value.trim();\n\t\t\t\tpreviewAuthor.textContent = v;\n\t\t\t\tpreviewAuthor.classList.toggle('hidden', !v);\n\t\t\t}\n\n\t\t\tfunction syncCover(file) {\n\t\t\t\tif (!previewImg || !file) return;\n\t\t\t\tconst reader = new FileReader();\n\t\t\t\treader.onload = e => {\n\t\t\t\t\tpreviewImg.src = e.target.result;\n\t\t\t\t\tpreviewImg.classList.remove('hidden');\n\t\t\t\t\tif (previewPlaceholder) previewPlaceholder.classList.add('hidden');\n\t\t\t\t};\n\t\t\t\treader.readAsDataURL(file);\n\t\t\t}\n\n\t\t\tconst tagsInput = document.getElementById('tags');\n\n\t\t\tfunction syncTags() {\n\t\t\t\tif (!previewTags) return;\n\t\t\t\tconst vals = (tagsInput?.value || '').split(',').map(t => t.trim()).filter(Boolean);\n\t\t\t\tpreviewTags.innerHTML = '';\n\t\t\t\tpreviewTags.classList.toggle('hidden', vals.length === 0);\n\t\t\t\tvals.forEach(tag => {\n\t\t\t\t\tconst span = document.createElement('span');\n\t\t\t\t\tspan.className = 'inline-flex items-center rounded-full bg-secondary text-secondary-foreground px-2 py-0.5 text-xs font-medium';\n\t\t\t\t\tspan.textContent = tag;\n\t\t\t\t\tpreviewTags.appendChild(span);\n\t\t\t\t});\n\t\t\t}\n\n\t\t\ttitleInput?.addEventListener('input', syncTitle);\n\t\t\tauthorInput?.addEventListener('input', syncAuthor);\n\t\t\ttagsInput?.addEventListener('input', syncTags);\n\t\t\tcoverInput?.addEventListener('change', () => syncCover(coverInput.files?.[0]));\n\t\t});\n\t\t</script>")
